/* WebGL1 compositor: cached scene upload → low-resolution bloom → color/light pass.
 * No external runtime, no frame-by-frame framebuffer allocation. */
const VERT=`attribute vec2 aPosition;varying vec2 uv;void main(){uv=aPosition*.5+.5;gl_Position=vec4(aPosition,0.,1.);}`;
const FRAG=`precision mediump float;varying vec2 uv;uniform sampler2D scene;uniform sampler2D glow;uniform vec2 stepUV;uniform vec2 direction;uniform float mode;uniform float bloom;uniform float time;
void main(){vec4 c=texture2D(scene,uv);
if(mode<.5){float l=max(c.r,max(c.g,c.b));gl_FragColor=vec4(c.rgb*smoothstep(.60,.96,l),1.);return;}
if(mode<1.5){vec2 d=direction*stepUV;vec3 b=texture2D(scene,uv).rgb*.227027;b+=(texture2D(scene,uv+d*1.384615).rgb+texture2D(scene,uv-d*1.384615).rgb)*.316216;b+=(texture2D(scene,uv+d*3.230769).rgb+texture2D(scene,uv-d*3.230769).rgb)*.070270;gl_FragColor=vec4(b,1.);return;}
vec3 color=c.rgb+texture2D(glow,uv).rgb*bloom;color=(color-.5)*1.035+.5;color*=vec3(1.025,1.012,.99);float vignette=1.-.12*smoothstep(.20,.74,distance(uv,vec2(.5)));color*=vignette;gl_FragColor=vec4(color,1.);}`;
export class GPUCompositor{
 constructor(canvas){this.canvas=canvas;this.ready=false;this.lost=false;try{this.gl=canvas.getContext('webgl',{alpha:false,antialias:false,depth:false,stencil:false,powerPreference:'high-performance',preserveDrawingBuffer:false});if(this.gl)this.init();}catch(e){this.error=String(e);}canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();this.lost=true;this.ready=false;});canvas.addEventListener('webglcontextrestored',()=>{this.lost=false;this.init();this.width=0;});}
 init(){const gl=this.gl,shader=(type,src)=>{const s=gl.createShader(type);gl.shaderSource(s,src);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))throw Error(gl.getShaderInfoLog(s));return s;};this.program=gl.createProgram();gl.attachShader(this.program,shader(gl.VERTEX_SHADER,VERT));gl.attachShader(this.program,shader(gl.FRAGMENT_SHADER,FRAG));gl.linkProgram(this.program);if(!gl.getProgramParameter(this.program,gl.LINK_STATUS))throw Error('WebGL link: '+gl.getProgramInfoLog(this.program));gl.useProgram(this.program);const buf=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,buf);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array([-1,-1,1,-1,-1,1,1,1]),gl.STATIC_DRAW);const a=gl.getAttribLocation(this.program,'aPosition');gl.enableVertexAttribArray(a);gl.vertexAttribPointer(a,2,gl.FLOAT,false,0,0);this.u=Object.fromEntries(['scene','glow','stepUV','direction','mode','bloom','time'].map(n=>[n,gl.getUniformLocation(this.program,n)]));gl.uniform1i(this.u.scene,0);gl.uniform1i(this.u.glow,1);this.source=this.texture();this.targets=Array.from({length:2},()=>({texture:this.texture(),framebuffer:gl.createFramebuffer()}));this.ready=true;}
 texture(){const gl=this.gl,t=gl.createTexture();gl.bindTexture(gl.TEXTURE_2D,t);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MIN_FILTER,gl.LINEAR);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MAG_FILTER,gl.LINEAR);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_S,gl.CLAMP_TO_EDGE);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_T,gl.CLAMP_TO_EDGE);return t;}
 resize(width,height){if(this.width===width&&this.height===height)return;this.width=width;this.height=height;this.bw=Math.max(1,Math.floor(width/3));this.bh=Math.max(1,Math.floor(height/3));const gl=this.gl;gl.activeTexture(gl.TEXTURE0);for(const t of this.targets){gl.bindTexture(gl.TEXTURE_2D,t.texture);gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,this.bw,this.bh,0,gl.RGBA,gl.UNSIGNED_BYTE,null);gl.bindFramebuffer(gl.FRAMEBUFFER,t.framebuffer);gl.framebufferTexture2D(gl.FRAMEBUFFER,gl.COLOR_ATTACHMENT0,gl.TEXTURE_2D,t.texture,0);if(gl.checkFramebufferStatus(gl.FRAMEBUFFER)!==gl.FRAMEBUFFER_COMPLETE)throw Error('Framebuffer unsupported');}gl.bindFramebuffer(gl.FRAMEBUFFER,null);}
 pass(texture,target,mode,dx=0,dy=0){const gl=this.gl;gl.bindFramebuffer(gl.FRAMEBUFFER,target?.framebuffer||null);gl.viewport(0,0,target?this.bw:this.width,target?this.bh:this.height);gl.activeTexture(gl.TEXTURE0);gl.bindTexture(gl.TEXTURE_2D,texture);gl.uniform1f(this.u.mode,mode);gl.uniform2f(this.u.direction,dx,dy);gl.uniform2f(this.u.stepUV,1/this.bw,1/this.bh);gl.drawArrays(gl.TRIANGLE_STRIP,0,4);}
 present(surface,quality='balanced',time=0){if(!this.ready)return;const gl=this.gl;this.resize(surface.width,surface.height);gl.useProgram(this.program);gl.activeTexture(gl.TEXTURE1);gl.bindTexture(gl.TEXTURE_2D,this.source);gl.activeTexture(gl.TEXTURE0);gl.bindTexture(gl.TEXTURE_2D,this.source);gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL,true);gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,gl.RGBA,gl.UNSIGNED_BYTE,surface);gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL,false);if(quality!=='economy'){this.pass(this.source,this.targets[0],0);this.pass(this.targets[0].texture,this.targets[1],1,1,0);this.pass(this.targets[1].texture,this.targets[0],1,0,1);}gl.activeTexture(gl.TEXTURE1);gl.bindTexture(gl.TEXTURE_2D,this.targets[0].texture);gl.uniform1f(this.u.bloom,quality==='economy'?0:.28);gl.uniform1f(this.u.time,time);this.pass(this.source,null,2);}
}
